import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec3, float, mix, uniform, time } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshStandardNodeMaterial({
    metalness: 0.5,
    roughness: 0.55,
  });

  const map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.RepeatWrapping;
  map.wrapT = THREE.RepeatWrapping;

  const uvNode = uv();
  const baseTex = texture(map, uvNode);

  // engineered gradient overlay: ink -> surface diagonal gradient blended with brushed metal
  const ink = vec3(0x16 / 255, 0x16 / 255, 0x1d / 255);
  const surface = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255);
  const accent = vec3(0xff / 255, 0x2a / 255, 0x38 / 255);

  const gradientMix = uvNode.x.add(uvNode.y).mul(0.5);
  const engineeredGradient = mix(surface, ink, gradientMix);

  // subtle grain via simple hash-based noise using uv + no time-based animation (static composition)
  const grainSeed = uvNode.x.mul(1234.5).add(uvNode.y.mul(789.3));
  const grain = grainSeed.sin().mul(43758.5453).fract().sub(0.5).mul(0.03);

  const blended = mix(engineeredGradient, baseTex.rgb, float(0.65)).add(grain);

  // thin accent edge line at bottom for signal color detail
  const edgeMask = uvNode.y.smoothstep(0.0, 0.02);
  const withAccentEdge = mix(accent, blended, edgeMask);

  material.colorNode = withAccentEdge;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);
  mesh.name = 'hub-features-card-3-plane';

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return mesh;
}
